using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evaluation;

[TestClass]
public class EvaluationTests
{
    private static DistributedApplicationTestingBuilder _appHost = null!;
    private static DistributedApplication _app = null!;

    [ClassInitialize]
    public static async Task ClassInitialize(TestContext context)
    {
        _appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        _app = await _appHost.BuildAsync();
        await _app.StartAsync();
    }

    [ClassCleanup]
    public static async Task ClassCleanup()
    {
        if (_app is not null)
        {
            await _app.DisposeAsync();
        }
    }

    [TestMethod]
    public async Task BasicGreeting_IsCoherentAndRelevant()
    {
        var chatClient = _app.Services.GetRequiredService<IChatClient>();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Hello, how can you help me?")
        };

        var response = await chatClient.GetResponseAsync(messages);
        var responseText = response.Text;

        Assert.IsFalse(
            string.IsNullOrWhiteSpace(responseText),
            "Response should not be empty.");

        // Evaluate quality using AI-based evaluators
        var evaluators = new IEvaluator[]
        {
            new CoherenceEvaluator(),
            new RelevanceEvaluator(),
            new FluencyEvaluator()
        };

        var chatConfiguration = new ChatConfiguration(chatClient);
        var turnContext = new TurnContext();

        foreach (var evaluator in evaluators)
        {
            await evaluator.InitializeAsync([], chatConfiguration);
        }

        var results = new List<EvaluationResult>();
        foreach (var evaluator in evaluators)
        {
            var result = await evaluator.EvaluateAsync(messages, response, chatConfiguration, turnContext);
            results.Add(result);
        }

        foreach (var result in results)
        {
            foreach (var metric in result.Metrics)
            {
                if (metric.Value is NumericMetricValue numericValue)
                {
                    Assert.IsTrue(
                        numericValue.Value >= 3,
                        $"Metric '{metric.Key}' scored {numericValue.Value}, expected >= 3.");
                }
            }
        }
    }

    [TestMethod]
    public async Task FactualQuestion_IsGroundedAndRelevant()
    {
        var chatClient = _app.Services.GetRequiredService<IChatClient>();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await chatClient.GetResponseAsync(messages);
        var responseText = response.Text;

        Assert.IsFalse(
            string.IsNullOrWhiteSpace(responseText),
            "Response should not be empty.");

        Assert.IsTrue(
            responseText.Contains("Paris", StringComparison.OrdinalIgnoreCase),
            "Response should mention Paris.");
    }

    [TestMethod]
    public async Task MultiTurnConversation_MaintainsContext()
    {
        var chatClient = _app.Services.GetRequiredService<IChatClient>();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "My name is Alice.")
        };

        var firstResponse = await chatClient.GetResponseAsync(messages);

        messages.Add(new ChatMessage(ChatRole.Assistant, firstResponse.Text));
        messages.Add(new ChatMessage(ChatRole.User, "What is my name?"));

        var secondResponse = await chatClient.GetResponseAsync(messages);
        var responseText = secondResponse.Text;

        Assert.IsTrue(
            responseText.Contains("Alice", StringComparison.OrdinalIgnoreCase),
            "Agent should recall the user's name from prior context.");
    }
}

